function gridSpec(cols, gutter, total){
  cols=Math.max(1,Math.round(+cols||12)); gutter=Math.max(0,+gutter||16); total=Math.max(1,+total||1140);
  var colWidth=(total - gutter*(cols-1))/cols;
  if(colWidth<=0) return {error:'列数或间距过大，宽度不足'};
  var positions=[];
  for(var i=0;i<cols;i++){ positions.push(Math.round((i*(colWidth+gutter))*100)/100); }
  return {cols:cols, gutter:gutter, total:total, colWidth:Math.round(colWidth*100)/100, positions:positions};
}
var EXPORTS={gridSpec:gridSpec};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.GridOverlayForgePure = EXPORTS; }
